BEGIN;
SELECT pg_advisory_xact_lock(729306214);
CREATE SCHEMA IF NOT EXISTS mzg_private;
REVOKE ALL ON SCHEMA mzg_private FROM PUBLIC;
  
 CREATE TABLE IF NOT EXISTS mzg_private.users(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,phone TEXT NOT NULL DEFAULT '',city TEXT NOT NULL DEFAULT 'Lahore',country TEXT NOT NULL DEFAULT 'Pakistan',salt TEXT NOT NULL,password_hash TEXT NOT NULL,hash_n BIGINT NOT NULL DEFAULT 32768,hash_p BIGINT NOT NULL DEFAULT 3,verified_at TEXT,created_at TEXT NOT NULL,terms_at TEXT NOT NULL,suspended BIGINT NOT NULL DEFAULT 0,role TEXT NOT NULL DEFAULT 'customer' CHECK(role IN ('customer','admin')),avatar BYTEA,updated_at TEXT);
 CREATE TABLE IF NOT EXISTS mzg_private.sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES mzg_private.users(id) ON DELETE CASCADE,csrf TEXT NOT NULL,created_at BIGINT NOT NULL,last_seen BIGINT NOT NULL,expires BIGINT NOT NULL,admin_verified BIGINT NOT NULL DEFAULT 0);
 CREATE TABLE IF NOT EXISTS mzg_private.tokens(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES mzg_private.users(id) ON DELETE CASCADE,purpose TEXT NOT NULL,target TEXT,expires BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS mzg_private.bookings(id TEXT PRIMARY KEY,reference TEXT NOT NULL UNIQUE,user_id TEXT NOT NULL REFERENCES mzg_private.users(id),car_id BIGINT NOT NULL,car_name TEXT NOT NULL,car_image TEXT NOT NULL,pickup_at TEXT NOT NULL,return_at TEXT NOT NULL,location TEXT NOT NULL,phone TEXT NOT NULL,requests TEXT NOT NULL DEFAULT '',days BIGINT NOT NULL,daily_rate BIGINT NOT NULL,estimate BIGINT NOT NULL,quoted_price BIGINT,prepaid_amount BIGINT NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Confirmed','Active','Completed','Cancelled','Rejected')),owner_note TEXT NOT NULL DEFAULT '',cancellation_fee BIGINT NOT NULL DEFAULT 0,policy TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,idempotency TEXT NOT NULL,UNIQUE(user_id,idempotency));
 CREATE TABLE IF NOT EXISTS mzg_private.booking_events(id BIGSERIAL PRIMARY KEY,booking_id TEXT NOT NULL REFERENCES mzg_private.bookings(id),actor_id TEXT NOT NULL REFERENCES mzg_private.users(id),status TEXT NOT NULL,note TEXT NOT NULL,created_at TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS mzg_private.limits(key TEXT PRIMARY KEY,count BIGINT NOT NULL,expires BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS mzg_private.metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
 CREATE INDEX IF NOT EXISTS bookings_user ON mzg_private.bookings(user_id,created_at);
 CREATE INDEX IF NOT EXISTS sessions_user ON mzg_private.sessions(user_id);
 CREATE TABLE IF NOT EXISTS mzg_private.admin_access(user_id TEXT PRIMARY KEY REFERENCES mzg_private.users(id),role TEXT NOT NULL CHECK(role IN ('owner','admin','staff')),permissions TEXT NOT NULL DEFAULT '[]',mfa_secret TEXT,mfa_pending TEXT,mfa_pending_expires BIGINT,mfa_last BIGINT NOT NULL DEFAULT -1);
 CREATE TABLE IF NOT EXISTS mzg_private.admin_audit(id BIGSERIAL PRIMARY KEY,actor_id TEXT,action TEXT NOT NULL,resource TEXT NOT NULL,success BIGINT NOT NULL,created_at TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS mzg_private.vehicles(id BIGSERIAL PRIMARY KEY,reference TEXT NOT NULL UNIQUE,data TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('available','unavailable','maintenance','archived')),updated_at TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS mzg_private.cms_pages(slug TEXT PRIMARY KEY,file TEXT NOT NULL UNIQUE,draft TEXT NOT NULL,published TEXT NOT NULL,revision BIGINT NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS mzg_private.cms_revisions(id BIGSERIAL PRIMARY KEY,slug TEXT NOT NULL REFERENCES mzg_private.cms_pages(slug),content TEXT NOT NULL,actor_id TEXT NOT NULL,created_at TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS mzg_private.site_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS mzg_private.media(id TEXT PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,alt TEXT NOT NULL,width BIGINT NOT NULL,height BIGINT NOT NULL,data BYTEA NOT NULL,small BYTEA NOT NULL,created_at TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS mzg_private.booking_internal(booking_id TEXT PRIMARY KEY REFERENCES mzg_private.bookings(id),note TEXT NOT NULL DEFAULT '');
 CREATE TABLE IF NOT EXISTS mzg_private.customer_notes(user_id TEXT PRIMARY KEY REFERENCES mzg_private.users(id),note TEXT NOT NULL DEFAULT '');
 CREATE TABLE IF NOT EXISTS mzg_private.payments(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL REFERENCES mzg_private.bookings(id),amount BIGINT NOT NULL CHECK(amount<>0),kind TEXT NOT NULL CHECK(kind IN ('payment','refund')),reference TEXT NOT NULL UNIQUE,note TEXT NOT NULL,actor_id TEXT NOT NULL,created_at TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS mzg_private.backups(id TEXT PRIMARY KEY,filename TEXT NOT NULL,sha256 TEXT NOT NULL,size BIGINT NOT NULL,created_at TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS mzg_private.admin_invitations(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES mzg_private.users(id),actor_id TEXT NOT NULL REFERENCES mzg_private.users(id),role TEXT NOT NULL,permissions TEXT NOT NULL,expires BIGINT NOT NULL);
 CREATE INDEX IF NOT EXISTS audit_date ON mzg_private.admin_audit(created_at);
 CREATE UNIQUE INDEX IF NOT EXISTS vehicles_registration ON mzg_private.vehicles(upper(replace(replace(coalesce((data::jsonb->>'registration'),''),' ',''),'-',''))) WHERE (data::jsonb->>'registration') IS NOT NULL AND (data::jsonb->>'registration')<>'';
 
CREATE UNIQUE INDEX IF NOT EXISTS users_email_ci ON mzg_private.users(lower(email));
CREATE UNIQUE INDEX IF NOT EXISTS vehicles_reference_ci ON mzg_private.vehicles(lower(reference));
ALTER TABLE mzg_private.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE mzg_private.sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE mzg_private.tokens ENABLE ROW LEVEL SECURITY;
ALTER TABLE mzg_private.bookings ENABLE ROW LEVEL SECURITY;
ALTER TABLE mzg_private.booking_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE mzg_private.limits ENABLE ROW LEVEL SECURITY;
ALTER TABLE mzg_private.metadata ENABLE ROW LEVEL SECURITY;
ALTER TABLE mzg_private.admin_access ENABLE ROW LEVEL SECURITY;
ALTER TABLE mzg_private.admin_audit ENABLE ROW LEVEL SECURITY;
ALTER TABLE mzg_private.vehicles ENABLE ROW LEVEL SECURITY;
ALTER TABLE mzg_private.cms_pages ENABLE ROW LEVEL SECURITY;
ALTER TABLE mzg_private.cms_revisions ENABLE ROW LEVEL SECURITY;
ALTER TABLE mzg_private.site_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE mzg_private.media ENABLE ROW LEVEL SECURITY;
ALTER TABLE mzg_private.booking_internal ENABLE ROW LEVEL SECURITY;
ALTER TABLE mzg_private.customer_notes ENABLE ROW LEVEL SECURITY;
ALTER TABLE mzg_private.payments ENABLE ROW LEVEL SECURITY;
ALTER TABLE mzg_private.backups ENABLE ROW LEVEL SECURITY;
ALTER TABLE mzg_private.admin_invitations ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS mzg_private.booking_operations(booking_id TEXT PRIMARY KEY REFERENCES mzg_private.bookings(id),started_at TEXT,returned_at TEXT);
CREATE TABLE IF NOT EXISTS mzg_private.maintenance_blocks(id TEXT PRIMARY KEY,car_id BIGINT NOT NULL REFERENCES mzg_private.vehicles(id),starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,reason TEXT NOT NULL,actor_id TEXT NOT NULL,created_at TEXT NOT NULL,cancelled_at TEXT);
CREATE INDEX IF NOT EXISTS maintenance_car_dates ON mzg_private.maintenance_blocks(car_id,starts_at,ends_at);
ALTER TABLE mzg_private.booking_operations ENABLE ROW LEVEL SECURITY;
ALTER TABLE mzg_private.maintenance_blocks ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS mzg_private.email_jobs(id TEXT PRIMARY KEY,dedupe TEXT NOT NULL UNIQUE,recipient TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,html TEXT NOT NULL,kind TEXT NOT NULL,booking_id TEXT,status TEXT NOT NULL,attempts BIGINT NOT NULL DEFAULT 0,available_at BIGINT NOT NULL,leased_until BIGINT,created_at TEXT NOT NULL,sent_at TEXT,last_error TEXT);CREATE INDEX IF NOT EXISTS email_jobs_due ON mzg_private.email_jobs(status,available_at);
ALTER TABLE mzg_private.email_jobs ENABLE ROW LEVEL SECURITY;
INSERT INTO mzg_private.metadata(key,value) VALUES('schema_version','4') ON CONFLICT(key) DO UPDATE SET value=excluded.value;
COMMIT;
